// The delays and modulation effects of misceffects.lib, phaflangers.lib and delays.lib as modules, generated by
// build-faust-library-modules.mjs as the filters (faust-filter-modules.mjs).
//
// - Times in ms on a log scale, rates in Hz on a log scale; no smoothing.
// - Mix: from the dry sound (0) to the effect alone (1); the echoes of a delay are the effect.
//
// Family: Lib delays (in FAUST_LIBRARY_FAMILIES), with the Flanger Stereo, the Phaser Stereo and the Tape Stop
// of demos.lib.

const MS = (index, label, deflt, min, max) => `hslider("[${index}]${label}[unit:ms][scale:log]", ${deflt}, ${min}, ${max}, 0.01) / 1000`;
const HZ = (index, label, deflt, min, max) => `hslider("[${index}]${label}[unit:Hz][scale:log]", ${deflt}, ${min}, ${max}, 0.001)`;
const MIX = (index, deflt) => `mix = hslider("[${index}]Mix", ${deflt}, 0, 1, 0.01);
// from the dry sound to the effect
mixed(fx) = _ <: _, fx : \\(dry, wet).(dry + mix * (wet - dry));`;
const AUDIO = { inlets: "audio", outlets: "audio" };

export const DELAY_MODULES = [
    {
        family: "Lib delays", name: "Echo", file: "Echo", source: "ef.echo (misceffects.lib)", ...AUDIO,
        summary: [
            "Echo: a delay line whose output is fed back: an echo every Time, the first Feedback times the sound, each next one Feedback times the previous one",
            "Time: from 1 ms to 2 s, a whole number of samples (moving it clicks: the Delay module glides)",
            "Mix: from the dry sound to the echoes alone",
        ],
        body: `// ef.echo gives the dry sound and its echoes: the echoes alone are its output minus its input
process = mixed(echoes);
echoes = _ <: ef.echo(2, time, feedback), _ : -;

time = ${MS(0, "Time", 300, 1, 2000)};
feedback = hslider("[1]Feedback", 0.4, 0, 0.99, 0.01);
${MIX(2, 0.5)}`,
    },
    {
        family: "Lib delays", name: "Delay", file: "Delay", source: "de.fdelay (delays.lib)", ...AUDIO,
        summary: [
            "Delay, fractional, with feedback: its time glides when it moves, which transposes the delayed sound, as a tape",
            "Time: from 1 ms to 1 s; an LFO dropped on it gives a chorus, a vibrato or a flutter",
            "Feedback: the part of the delayed sound sent back; Mix: from the dry sound to the delayed one alone",
        ],
        body: `// the loop is Time long: fdelay of Time - 1 sample, plus the sample of the feedback (~); the output mem makes
// the delay of the sound Time too (as pf.flanger_mono)
process = mixed(((+ : de.fdelay(262144, max(0, time * ma.SR - 1))) ~ *(feedback)) : mem);

time = ${MS(0, "Time", 300, 1, 1000)};
feedback = hslider("[1]Feedback", 0.3, 0, 0.99, 0.01);
${MIX(2, 0.5)}`,
    },
    {
        family: "Lib delays", name: "Flanger", file: "Flanger", source: "pf.flanger_mono (phaflangers.lib)", ...AUDIO,
        summary: [
            "Flanger: the sound and a copy delayed by a few ms, the delay swept by a sine LFO: the notches of the comb move",
            "Delay: the center of the sweep (0.1 to 10 ms); Sweep: its extent, from 0 (the delay fixed: an LFO can be dropped on Delay) to 1 (from 0 to twice the delay); Rate: the LFO",
            "Depth: the level of the delayed copy; Feedback; Invert: the copy subtracted (notches at multiples of 1/Delay, instead of odd multiples of 1/(2 Delay))",
        ],
        body: `process = pf.flanger_mono(8192, delay * ma.SR * (1 + sweep * os.osc(rate)), depth, feedback, invert);

delay = ${MS(0, "Delay", 2, 0.1, 10)};
sweep = hslider("[1]Sweep", 0.7, 0, 1, 0.01);
rate = ${HZ(2, "Rate", 0.3, 0.01, 10)};
depth = hslider("[3]Depth", 1, 0, 1, 0.01);
feedback = hslider("[4]Feedback", 0.5, 0, 0.95, 0.01);
invert = checkbox("[5]Invert");`,
    },
    {
        family: "Lib delays", name: "Phaser", file: "Phaser", source: "pf.phaser2_mono (phaflangers.lib)", ...AUDIO,
        summary: [
            "Phaser: the sound and its copy through a chain of all pass filters whose notches are swept by a sine LFO",
            "Notches: 2, 4 or 8; Min and Max: the range of the sweep of the first notch; Ratio: from one notch to the next; Width: of the notches",
            "Rate: the LFO; Depth: the level of the copy (0: the dry sound); Feedback; Invert",
        ],
        body: `process = _ <: pf.phaser2_mono(2, 0, width, low, ratio, high, rate, depth, feedback, invert),
    pf.phaser2_mono(4, 0, width, low, ratio, high, rate, depth, feedback, invert),
    pf.phaser2_mono(8, 0, width, low, ratio, high, rate, depth, feedback, invert) : ba.selectn(3, notches);

notches = hslider("[0]Notches[style:menu{'2':0;'4':1;'8':2}]", 1, 0, 2, 1);
rate = ${HZ(1, "Rate", 0.5, 0.01, 10)};
low = ${HZ(2, "Min", 100, 20, 5000)};
high = ${HZ(3, "Max", 800, 50, 20000)} : max(low);
ratio = hslider("[4]Ratio[scale:log]", 1.5, 1.1, 4, 0.001);
width = ${HZ(5, "Width", 1000, 10, 5000)};
depth = hslider("[6]Depth", 1, 0, 1, 0.01);
feedback = hslider("[7]Feedback", 0, -0.95, 0.95, 0.01);
invert = checkbox("[8]Invert");`,
    },
    {
        family: "Lib delays", name: "Vibrato", file: "Vibrato", source: "de.fdelay (delays.lib)", ...AUDIO,
        summary: [
            "Vibrato: the sound through a delay swept by a sine LFO, which moves its pitch",
            "Rate: the LFO (0.5 to 20 Hz); Depth: the largest rise of the pitch, in cents (the delay swept is computed from it)",
        ],
        body: `// A delay d(t) = D (1 + sin(2 pi f t)) plays the sound at the speed 1 - d'(t), which rises at most to
// 1 + 2 pi f D: for a rise of c cents, D = (2^(c/1200) - 1) / (2 pi f).
process = de.fdelay(16384, d * ma.SR)
with {
    D = (pow(2, depth / 1200) - 1) / (2 * ma.PI * rate);
    d = D * (1 + os.osc(rate));
};

rate = ${HZ(0, "Rate", 5, 0.5, 20)};
depth = hslider("[1]Depth[unit:cent]", 20, 0, 100, 0.1);`,
    },
    {
        family: "Lib delays", name: "Pitch Shifter", file: "PitchShifter", source: "ef.transpose_windowed (misceffects.lib)", ...AUDIO,
        summary: [
            "Pitch shifter: two Hann windowed taps of a delay line swept at the speed of the shift, which overlap without clicks",
            "Two taps, not four: with four, the frequencies at odd multiples of 2 SR / Window cancel for good (every 80 Hz from 40 Hz with 50 ms); with two, none is lost (-3 dB at worst, on average)",
            "Shift: in semitones (-24 to +24); Window: the length of the taps (short: less delay, longer: smoother)",
            "Mix: from the dry sound to the shifted one",
        ],
        body: `// two taps: with P taps a quarter of a window apart (P = 4), their Hann weights cancel the frequencies whose
// half period is that spacing, at every instant
process = mixed(ef.transpose_windowed(2, window * ma.SR, shift));

shift = hslider("[0]Shift[unit:st]", 7, -24, 24, 0.01);
window = ${MS(1, "Window", 50, 10, 200)};
${MIX(2, 1)}`,
    },
    {
        family: "Lib delays", name: "Granular", file: "Granular", source: "ef.granular (misceffects.lib)", ...AUDIO,
        summary: [
            "Granulator: three voices replay Hann windowed grains of the sound, taken Position back, which overlap into a texture (with four, shifted grains would cancel some frequencies for good, as in the Pitch Shifter)",
            "Grain: their duration; Shift: their pitch, in semitones; Jitter: a random part of their position; with no shift and no jitter, the sound delayed by Position",
            "Mix: from the dry sound to the grains (the line holds 65536 samples: 1.36 s at 48 kHz)",
        ],
        body: `process = mixed(ef.granular(3, grain, pow(2, shift / 12), position, jitter));

grain = ${MS(0, "Grain", 100, 10, 300)};
shift = hslider("[1]Shift[unit:st]", 0, -24, 24, 0.01);
position = hslider("[2]Position[unit:ms]", 100, 0, 300, 0.1) / 1000;
jitter = hslider("[3]Jitter[unit:ms]", 0, 0, 300, 0.1) / 1000;
${MIX(4, 1)}`,
    },
    {
        family: "Lib delays", name: "Dimension Expander", file: "DimensionExpander", source: "ef.xferDimensionExpander (misceffects.lib)", inlets: "left; right", outlets: "left; right",
        summary: [
            "Stereo widener in the spirit of the Roland Dimension D: four delay taps of the mono sum, modulated, spread between the two sides",
            "Size: the delays of the taps (15 to 25 ms at 0, 115 to 189 ms at 1); Wet: their level, the dry sound always at its own",
        ],
        body: `process = ef.xferDimensionExpander(size, wet);

size = hslider("[0]Size", 0.3, 0, 1, 0.01);
wet = hslider("[1]Wet", 0.5, 0, 1, 0.01);`,
    },
];
